contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _minSum, address _log, uint _minSum2, address _log2) public {
        // Before initialization, setters should succeed and store the values.
        c.SetMinSum(_minSum);
        c.SetLogFile(_log);
        bool preOk = (c.MinSum() == _minSum && address(c.Log()) == _log);

        c.Initialized();

        // After initialization, both setters must revert.
        bool revertMinSum;
        try c.SetMinSum(_minSum2) { revertMinSum = false; } catch { revertMinSum = true; }

        bool revertLogFile;
        try c.SetLogFile(_log2) { revertLogFile = false; } catch { revertLogFile = true; }

        assert(preOk && revertMinSum && revertLogFile && c.MinSum() == _minSum && address(c.Log()) == _log);
    }
}

